import React from 'react';
import { SolutionResponse } from '../../types';

interface ResultsDisplayProps {
    result: SolutionResponse;
}

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {

    const formatNumber = (value: number): string => {
        if (value === 0) return "0";

        return value.toLocaleString('ru-RU', {
            minimumFractionDigits: 0,
            maximumFractionDigits: 10,
            useGrouping: false
        }).replace(',', '.');
    };

    const formatError = (value: number): string => {
        if (value === 0) return "0";
        return value.toFixed(12).replace(/\.?0+$/, '');
    };

    return (
        <div className="space-y-6 text-slate-800">
            <div className="p-4 rounded-lg border border-slate-200 bg-slate-50">
                <div className="flex items-center gap-2">
                    <span className="text-sm font-medium">
                        {result.diagonalDominance
                            ? '✓ Диагональное преобладание выполнено'
                            : '⚠ Диагональное преобладание отсутствует (сделана перестановка)'}
                    </span>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                    <div className="text-xs font-bold text-slate-400 uppercase mb-1">Определитель</div>
                    <div className="text-xl font-mono font-bold text-slate-900">
                        {formatNumber(result.determinant)}
                    </div>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                    <div className="text-xs font-bold text-slate-400 uppercase mb-1">Норма матрицы</div>
                    <div className="text-xl font-mono font-bold text-slate-900">
                        {formatNumber(result.matrixNorm)}
                    </div>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                    <div className="text-xs font-bold text-slate-400 uppercase mb-1">Итераций</div>
                    <div className="text-xl font-mono font-bold text-slate-900">
                        {result.iterations}
                    </div>
                </div>
            </div>

            <div className="bg-slate-50 rounded-lg p-5 border border-slate-200">
                <h3 className="text-sm font-bold uppercase text-slate-500 mb-4 tracking-wider">Вектор неизвестных (x):</h3>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                    {result.solution.map((value, index) => (
                        <div key={index} className="bg-white p-3 rounded-md border border-slate-200">
                            <div className="text-[10px] text-slate-400 mb-1 font-bold">x[{index + 1}]</div>
                            <div className="font-mono font-semibold text-base">
                                {formatNumber(value)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-slate-50 rounded-lg p-5 border border-slate-200">
                <h3 className="text-sm font-bold uppercase text-slate-500 mb-4 tracking-wider">Вектор невязки (r):</h3>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                    {result.residual.map((value, index) => (
                        <div key={index} className="bg-white p-3 rounded-md border border-slate-100">
                            <div className="text-[10px] text-slate-400 mb-1 font-bold">r[{index + 1}]</div>
                            <div className="font-mono text-sm text-slate-600">
                                {formatNumber(value)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-slate-50 rounded-lg p-5 border border-slate-200">
                <p className="text-sm font-medium">
                    {result.message}
                </p>
                <div className="bg-white p-3 rounded-md border border-slate-100">
                    <span className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">Макс. погрешность:</span>
                    <span className="font-mono text-sm">
                        {result.iterationHistory && result.iterationHistory.length > 0
                            ? formatError(result.iterationHistory[result.iterationHistory.length - 1].maxError)
                            : 'N/A'}
                    </span>
                </div>
            </div>
        </div>
    );
};
